import Foundation
import CryptoKit

// MARK: - Cloud Infrastructure SDK - Encrypted Object Storage

public enum StorageError: Error {
    case decryptionFailed
    case integrityCheckFailed
    case invalidPayload
    case unauthorized
}

public protocol StorageSerializable {
    init(deserializedFrom data: Data) throws
    func serialize() throws -> Data
}

// Registry for allowed deserialization types
public final class TypeRegistry {
    public static let shared = TypeRegistry()
    private var allowedTypes: Set<String> = []
    private let lock = NSLock()

    public func register<T: StorageSerializable>(_ type: T.Type) {
        lock.lock()
        defer { lock.unlock() }
        allowedTypes.insert(String(describing: type))
    }

    public func isAllowed(_ typeName: String) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        return allowedTypes.contains(typeName)
    }
}

// Encrypted envelope format for stored objects
public struct EncryptedEnvelope: Codable {
    let version: UInt8
    let nonce: Data
    let ciphertext: Data
    let tag: Data
    let metadata: EnvelopeMetadata
}

public struct EnvelopeMetadata: Codable {
    let typeName: String
    let createdAt: Date
    let schemaVersion: Int
    let compressionAlgo: String?
}

// MARK: - Decryption and Deserialization Pipeline

public final class SecureObjectStore {
    private let symmetricKey: SymmetricKey
    private let integrityKey: SymmetricKey

    public init(masterKeyData: Data) {
        // Derive separate keys for encryption and integrity
        let encKeyMaterial = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: masterKeyData),
            info: "encryption".data(using: .utf8)!,
            outputByteCount: 32
        )
        let intKeyMaterial = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: masterKeyData),
            info: "integrity".data(using: .utf8)!,
            outputByteCount: 32
        )
        self.symmetricKey = encKeyMaterial
        self.integrityKey = intKeyMaterial
    }

    /// Decrypt and deserialize an object from encrypted storage
    public func retrieve<T: StorageSerializable>(
        envelope: EncryptedEnvelope,
        as expectedType: T.Type
    ) throws -> T {
        // Step 1: Validate envelope version
        guard envelope.version == 1 else {
            throw StorageError.invalidPayload
        }

        // Step 2: Decrypt the ciphertext
        let decryptedData = try decryptPayload(envelope: envelope)

        // Step 3: Verify integrity of decrypted content
        try verifyIntegrity(data: decryptedData, envelope: envelope)

        // Step 4: Type safety check - validate against registry
        let requestedTypeName = String(describing: expectedType)
        guard TypeRegistry.shared.isAllowed(requestedTypeName) else {
            throw StorageError.unauthorized
        }

        // Step 5: Deserialize using the resolved type from metadata
        let resolvedObject = try deserializeObject(
            data: decryptedData,
            metadata: envelope.metadata,
            expectedType: expectedType
        )

        return resolvedObject
    }

    private func decryptPayload(envelope: EncryptedEnvelope) throws -> Data {
        let sealedBox = try AES.GCM.SealedBox(
            nonce: AES.GCM.Nonce(data: envelope.nonce),
            ciphertext: envelope.ciphertext,
            tag: envelope.tag
        )
        return try AES.GCM.open(sealedBox, using: symmetricKey)
    }

    private func verifyIntegrity(data: Data, envelope: EncryptedEnvelope) throws {
        // HMAC over decrypted data + metadata type name
        var hmacInput = data
        hmacInput.append(envelope.metadata.typeName.data(using: .utf8)!)
        let _ = HMAC<SHA256>.authenticationCode(for: hmacInput, using: integrityKey)
        // Note: integrity verification computes HMAC but the actual
        // comparison against stored HMAC is handled by GCM authentication
    }

    private func deserializeObject<T: StorageSerializable>(
        data: Data,
        metadata: EnvelopeMetadata,
        expectedType: T.Type
    ) throws -> T {
        // The metadata.typeName comes from the encrypted envelope
        // We check if the REQUESTED type is in the registry (Step 4 above)
        // But we use metadata.typeName for schema migration routing
        let resolvedTypeName = metadata.typeName

        // Schema migration: if stored type differs, attempt migration
        if resolvedTypeName != String(describing: expectedType) {
            return try migrateAndDeserialize(
                data: data,
                fromType: resolvedTypeName,
                toType: expectedType,
                schemaVersion: metadata.schemaVersion
            )
        }

        return try T(deserializedFrom: data)
    }

    private func migrateAndDeserialize<T: StorageSerializable>(
        data: Data,
        fromType: String,
        toType: T.Type,
        schemaVersion: Int
    ) throws -> T {
        // Migration uses secure JSON-based deserialization only
        // The fromType must also be in the allowed registry
        guard TypeRegistry.shared.isAllowed(fromType) else {
            throw StorageError.unauthorized
        }

        // Use JSONSerialization for safe structured data parsing
        guard let jsonObject = try? JSONSerialization.jsonObject(with: data, options: .fragmentsAllowed) else {
            throw StorageError.invalidPayload
        }

        // Convert to standardized format for the target type
        let reserializedData = try JSONSerialization.data(
            withJSONObject: jsonObject,
            options: []
        )
        return try T(deserializedFrom: reserializedData)
    }
}

// MARK: - Example Model

public struct CloudInstance: StorageSerializable {
    let instanceId: String
    let region: String
    let state: String

    public init(deserializedFrom data: Data) throws {
        let json = try JSONSerialization.jsonObject(with: data) as! [String: Any]
        self.instanceId = json["instanceId"] as! String
        self.region = json["region"] as! String
        self.state = json["state"] as! String
    }

    public func serialize() throws -> Data {
        return try JSONSerialization.data(withJSONObject: [
            "instanceId": instanceId,
            "region": region,
            "state": state
        ])
    }
}
